-- OBS Source Auto-Show/Hide based on focused app
-- Uses OBS WebSocket (built into OBS 28+)
-- No external dependencies - uses Hammerspoon's built-in websocket

obsWsPort = 4455
obsWsPassword = ""  -- Set your password from OBS > Tools > WebSocket Server Settings
obsSceneName = "windowscapturedseparately"  -- Your scene name in OBS

-- Map app names to OBS source names (must match sources in obsSceneName)
-- Only these apps trigger show/hide - others are ignored
obsSourceMap = {
    ["Safari"] = "safari",
    ["GitHub Desktop"] = "github",  -- Create this source in OBS
}

-- Cache for scene item IDs (source name -> item ID)
obsSceneItemIds = {}
obsWs = nil
obsConnected = false
obsRequestId = 0
obsRequestMap = {}  -- requestId -> sourceName

function obsNextRequestId()
    obsRequestId = obsRequestId + 1
    return tostring(obsRequestId)
end

function obsSendRequest(requestType, requestData, sourceName)
    if not obsWs or not obsConnected then return end
    local reqId = obsNextRequestId()
    if sourceName then
        obsRequestMap[reqId] = sourceName
    end
    local msg = hs.json.encode({
        op = 6,
        d = {
            requestType = requestType,
            requestId = reqId,
            requestData = requestData or {}
        }
    })
    obsWs:send(msg, false)  -- false = text frame (not binary)
end

function obsSetSourceVisible(sourceName, visible)
    local itemId = obsSceneItemIds[sourceName]
    if itemId then
        obsSendRequest("SetSceneItemEnabled", {
            sceneName = obsSceneName,
            sceneItemId = itemId,
            sceneItemEnabled = visible
        })
    end
end

function obsConnect()
    if obsWs then
        pcall(function() obsWs:close() end)
    end

    local url = "ws://127.0.0.1:" .. obsWsPort
    obsWs = hs.websocket.new(url, function(status, msg)
        if status == "received" then
            local ok, data = pcall(hs.json.decode, msg)
            if not ok or not data then return end

            -- Handle Hello (op 0) - send Identify
            if data.op == 0 then
                obsWs:send('{"op":1,"d":{"rpcVersion":1}}', false)

            -- Handle Identified (op 2)
            elseif data.op == 2 then
                obsConnected = true
                -- Fetch scene item IDs immediately
                for appName, sourceName in pairs(obsSourceMap) do
                    obsSendRequest("GetSceneItemId", {
                        sceneName = obsSceneName,
                        sourceName = sourceName
                    }, sourceName)
                end
                -- Also fetch nvim floating window source
                obsSendRequest("GetSceneItemId", {
                    sceneName = obsSceneName,
                    sourceName = "nvim"
                }, "nvim")

            -- Handle RequestResponse (op 7)
            elseif data.op == 7 then
                if data.d and data.d.requestStatus and data.d.requestStatus.result then
                    if data.d.responseData and data.d.responseData.sceneItemId then
                        local reqId = data.d.requestId
                        if obsRequestMap and obsRequestMap[reqId] then
                            obsSceneItemIds[obsRequestMap[reqId]] = data.d.responseData.sceneItemId
                        end
                    end
                end
            end
        elseif status == "closed" or status == "fail" then
            obsConnected = false
        end
    end)
end

local currentOBSSource = nil
local nvimSourceVisible = false

-- Watch for nvim floating window (iTerm2 window with title "nvim")
obsNvimWatcher = hs.timer.doEvery(0.3, function()
    if not obsConnected then return end

    local focusedWin = hs.window.focusedWindow()
    if focusedWin then
        local app = focusedWin:application()
        local title = focusedWin:title()

        -- Check if it's the nvim floating window
        if app and app:name() == "iTerm2" and title == "nvim" then
            if not nvimSourceVisible then
                obsSetSourceVisible("nvim", true)
                nvimSourceVisible = true
            end
            return
        end
    end

    -- nvim not focused, hide it if it was visible
    if nvimSourceVisible then
        obsSetSourceVisible("nvim", false)
        nvimSourceVisible = false
    end
end)

obsAppWatcher = hs.application.watcher.new(function(appName, eventType, app)
    if eventType == hs.application.watcher.activated and obsConnected then
        -- Hide previous source
        if currentOBSSource then
            obsSetSourceVisible(currentOBSSource, false)
        end

        -- Show new source if mapped
        local newSource = obsSourceMap[appName]
        if newSource then
            obsSetSourceVisible(newSource, true)
            currentOBSSource = newSource
        else
            currentOBSSource = nil
        end
    end
end)

-- Auto-start when OBS is running
local function obsAutoShowStart()
    print("[OBS Auto] Checking if OBS is running...")
    if obsIsRunning() then
        print("[OBS Auto] OBS is running, connecting...")
        obsConnect()
        hs.timer.doAfter(1, function()
            print("[OBS Auto] Starting app watcher")
            obsAppWatcher:start()
        end)
    else
        print("[OBS Auto] OBS is not running")
    end
end

-- Start on Hammerspoon load
hs.timer.doAfter(2, obsAutoShowStart)

-- Also start when OBS launches
obsLaunchWatcher = hs.application.watcher.new(function(appName, eventType, app)
    if appName == "OBS Studio" and eventType == hs.application.watcher.launched then
        hs.timer.doAfter(3, obsAutoShowStart)  -- Give OBS time to start websocket
    elseif appName == "OBS Studio" and eventType == hs.application.watcher.terminated then
        obsAppWatcher:stop()
        if obsWs then obsWs:close() end
        obsConnected = false
    end
end)
obsLaunchWatcher:start()

-- Manual toggle with Cmd+Ctrl+Option+O (optional)
local obsAutoShowEnabled = true
hs.hotkey.bind({"cmd", "ctrl", "alt"}, "O", function()
    obsAutoShowEnabled = not obsAutoShowEnabled
    if obsAutoShowEnabled then
        obsAutoShowStart()
        hs.alert.show("OBS auto-show: ON", 1.5)
    else
        obsAppWatcher:stop()
        if obsWs then obsWs:close() end
        obsConnected = false
        hs.alert.show("OBS auto-show: OFF", 1.5)
    end
end)

-- ============================================================================
-- Quake-style floating Ghostty scratchpad (Cmd+Ctrl+\)
-- Dedicated window identified by title "GhosttyFloat" — leaves other
-- Ghostty windows untouched.
-- ============================================================================
local ghosttyBundle = "com.mitchellh.ghostty"
local ghosttyBin   = "/Applications/Ghostty.app/Contents/MacOS/ghostty"
local floatTitle   = "GhosttyFloat"
local floatWin     = nil

local function floatWinAlive()
    return floatWin
        and floatWin:isStandard()
        and floatWin:application() ~= nil
end

local function findFloatWin()
    local app = hs.application.get(ghosttyBundle)
    if not app then return nil end
    for _, w in ipairs(app:allWindows()) do
        local t = w:title() or ""
        if t:find(floatTitle, 1, true) then return w end
    end
    return nil
end

local function positionFloat(win)
    if not win then return end
    local screen = hs.mouse.getCurrentScreen() or hs.screen.mainScreen()
    local f = screen:frame()
    local w = math.floor(f.w * 0.7)
    local h = math.floor(f.h * 0.55)
    win:setFrame({
        x = f.x + (f.w - w) / 2,
        y = f.y,
        w = w,
        h = h,
    })
    win:raise()
    win:focus()
end

local function spawnFloat()
    hs.task.new(ghosttyBin, nil, { "--title=" .. floatTitle }):start()
    hs.timer.waitUntil(
        function()
            floatWin = findFloatWin()
            return floatWin ~= nil
        end,
        function() positionFloat(floatWin) end,
        0.05
    )
end

local function floatShown()
    return floatWinAlive()
        and not floatWin:isMinimized()
        and floatWin:isVisible()
end

local function hideFloat()
    -- Move off-screen instead of minimizing (no Dock icon, instant restore)
    local f = floatWin:frame()
    floatWin._savedFrame = { x = f.x, y = f.y, w = f.w, h = f.h }
    local screen = hs.screen.mainScreen():fullFrame()
    floatWin:setTopLeft({ x = screen.x + screen.w + 100, y = f.y })
    -- Focus whatever was behind it
    local prev = hs.window.orderedWindows()
    for _, w in ipairs(prev) do
        if w ~= floatWin and w:isStandard() and w:isVisible() then
            w:focus()
            break
        end
    end
end

local function showFloat()
    if floatWin:isMinimized() then floatWin:unminimize() end
    positionFloat(floatWin)
end

local function toggleFloat()
    if not floatWinAlive() then
        floatWin = findFloatWin()
    end

    if not floatWinAlive() then
        spawnFloat()
        return
    end

    -- Treat off-screen-x as hidden, too
    local f = floatWin:frame()
    local screen = hs.screen.mainScreen():fullFrame()
    local offscreen = f.x >= screen.x + screen.w

    if floatShown() and not offscreen then
        hideFloat()
    else
        showFloat()
    end
end

hs.hotkey.bind({"cmd", "ctrl"}, "\\", toggleFloat)

-- ============================================================================
-- Nvim + Tmux cheatsheet popup (Cmd+Ctrl+Shift+Comma)
-- Loads ~/.hammerspoon/nvim-cheatsheet.html into a floating webview.
-- Hotkey toggles. Esc also closes.
-- ============================================================================
local cheatsheetWebview = nil
local cheatsheetEscTap = nil
local cheatsheetPath = os.getenv("HOME") .. "/.hammerspoon/nvim-cheatsheet.html"

local function cheatsheetLoadHTML()
    local f = io.open(cheatsheetPath, "r")
    if not f then return nil end
    local html = f:read("*all")
    f:close()
    return html
end

local function cheatsheetHide()
    if cheatsheetWebview then
        cheatsheetWebview:hide()
        cheatsheetWebview:delete()
        cheatsheetWebview = nil
    end
    if cheatsheetEscTap then
        cheatsheetEscTap:stop()
        cheatsheetEscTap = nil
    end
end

local function cheatsheetShow()
    local html = cheatsheetLoadHTML()
    if not html then
        hs.alert.show("Cheatsheet: nvim-cheatsheet.html not found")
        return
    end

    local screen = hs.screen.mainScreen():frame()
    local w = math.min(1200, math.floor(screen.w * 0.85))
    local h = math.min(760, math.floor(screen.h * 0.80))
    local rect = {
        x = screen.x + (screen.w - w) / 2,
        y = screen.y + (screen.h - h) / 2,
        w = w,
        h = h,
    }

    cheatsheetWebview = hs.webview.new(rect)
        :windowStyle({"titled", "closable", "nonactivating"})
        :windowTitle("Nvim + Tmux Cheatsheet")
        :allowTextEntry(false)
        :level(hs.drawing.windowLevels.floating)
        :shadow(true)
        :html(html)
        :bringToFront(true)
        :show()

    -- Esc closes
    cheatsheetEscTap = hs.eventtap.new({hs.eventtap.event.types.keyDown}, function(event)
        if event:getKeyCode() == 53 then  -- Escape
            cheatsheetHide()
            return true
        end
        return false
    end)
    cheatsheetEscTap:start()
end

hs.hotkey.bind({"cmd", "ctrl", "shift"}, ",", function()
    if cheatsheetWebview then
        cheatsheetHide()
    else
        cheatsheetShow()
    end
end)
